<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import AppSelect from '../../shared/AppSelect.vue';
import UserSearchSelect from '../../shared/UserSearchSelect.vue';
import { theme, toggleTheme } from '../../features/appearance/theme';
import { Eye, Layers3, LayoutDashboard, Users, CreditCard, BarChart3, Settings2, Search, Plus, ChevronDown, X, Check, CheckCircle2, Clock3, Sparkles, ShieldCheck, Bell, Download, MoreHorizontal, Menu, Gift, History, SlidersHorizontal, CircleHelp, RefreshCw, Moon, Sun, Home } from '@lucide/vue';
const nav=[{id:'overview',label:'Visão geral',icon:LayoutDashboard},{id:'users',label:'Usuários',icon:Users},{id:'subscriptions',label:'Assinaturas',icon:CreditCard},{id:'activity',label:'Histórico de ações',icon:History},{id:'settings',label:'Configurações',icon:Settings2}];
const first=['Marina','Lucas','Beatriz','Rafael','Ana','Pedro','Camila','Gabriel','Juliana','Bruno','Isabela','Felipe'];
const last=['Almeida','Costa','Ribeiro','Santos','Oliveira','Lima','Martins','Rocha'];
const makeUsers=()=>Array.from({length:96},(_,i)=>{const k=i%8,name=first[i%12]+' '+last[Math.floor(i/12)];return {id:i+1,name,email:name.toLowerCase().replaceAll(' ','.')+'@exemplo.com',status:k<4?'active':k===4?'manual':k===5?'canceled':k===6?'past_due':'free',joined:'2026-10-'+String(1+i%28).padStart(2,'0'),expires:'2026-11-'+String(1+i%28).padStart(2,'0'),disabled:false};});
const key='fluxo-admin-prototype-v1';let saved;try{saved=JSON.parse(localStorage.getItem(key)||'null');}catch{}
const users=ref(saved?.users||makeUsers());
const initialEvents=[{id:1,title:'Assinatura Pro ativada',detail:'Marina Almeida · pagamento confirmado',type:'subscription',time:'Hoje, 10:42'},{id:2,title:'Acesso cortesia concedido',detail:'Ana Almeida · 30 dias · parceria com criadores',type:'grant',time:'Hoje, 10:18'},{id:3,title:'Pagamento precisa de atenção',detail:'Camila Almeida · nova tentativa em 2 dias',type:'billing',time:'Hoje, 09:56'},{id:4,title:'Novo usuário no Tempozi',detail:'Gabriel Almeida · plano gratuito',type:'user',time:'Hoje, 09:31'}];
const events=ref(saved?.events||initialEvents);
const defaults={name:'Tempozi',email:'suporte@example.com',grace:'7',defaultGrant:'30',newAccounts:true,billingEmails:true,securityEmails:true,maintenance:false};
const settings=ref(saved?.settings||{...defaults}),draft=ref({...settings.value});
const view=ref('overview'),search=ref(''),statusFilter=ref('all'),originFilter=ref('all'),page=ref(1),sidebar=ref(false),period=ref('month'),modal=ref(null),selected=ref(null),toast=ref(''),queryInput=ref(null),formError=ref(''),submitting=ref(false);
let toastTimer,priorFocus;
const form=ref({user:'',duration:'30',until:'2026-11-30',reason:''});
const title=computed(()=>nav.find(n=>n.id===view.value)?.label||'Visão geral');
const counts=computed(()=>({total:users.value.length,active:users.value.filter(u=>['active','manual'].includes(u.status) ).length,paid:users.value.filter(u=>u.status==='active' ).length,manual:users.value.filter(u=>u.status==='manual' ).length,canceled:users.value.filter(u=>u.status==='canceled').length,pending:users.value.filter(u=>u.status==='past_due').length,free:users.value.filter(u=>u.status==='free').length}));
const revenue=computed(()=>counts.value.paid*19.9);
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
const labels={active:'Ativa',manual:'Cortesia',canceled:'Cancelada',past_due:'Pagamento pendente',free:'Gratuito'};
const dateFull=value=>new Date(value+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});
const initials=name=>name.split(' ').map(n=>n[0]).slice(0,2).join('');
const date=value=>new Date(value+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const filtered=computed(()=>users.value.filter(u=>(!search.value||(u.name+' '+u.email).toLowerCase().includes(search.value.toLowerCase()))&&(view.value!=='subscriptions'||u.status!=='free')&&(statusFilter.value==='all'||(statusFilter.value==='active'?['active','manual'].includes(u.status):u.status===statusFilter.value))&&(originFilter.value==='all'||(originFilter.value==='manual'?u.status==='manual':u.status==='active'))));
const totalPages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/8)));
const rows=computed(()=>filtered.value.slice((Math.min(page.value,totalPages.value)-1)*8,Math.min(page.value,totalPages.value)*8));
const grantTargets=computed(()=>users.value.filter(u=>!['active','past_due'].includes(u.status)&&!u.disabled));
const charts=computed(()=>period.value==='week'?[34,48,45,62,54,79,87]:[24,32,30,45,39,57,54,70,65,81,77,94]);
const chartLabels=computed(()=>period.value==='week'?['24 out','25 out','26 out','27 out','28 out','29 out','30 out']:['01 out','05 out','10 out','15 out','20 out','25 out','30 out']);
const line=computed(()=>charts.value.map((h,i)=>(i*600/(charts.value.length-1))+','+(150-h*1.4)).join(' '));
function persist(){localStorage.setItem(key,JSON.stringify({users:users.value,events:events.value,settings:settings.value}));}
function notify(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500);}
function go(id,filter='all'){view.value=id;statusFilter.value=filter;originFilter.value='all';search.value='';page.value=1;sidebar.value=false;window.scrollTo({top:0,behavior:'smooth'});}
function log(title,detail,type='admin'){events.value.unshift({id:Date.now(),title,detail,type,time:'Agora · Nicolas Moraes'});persist();}
function openGrant(user){form.value={user:user?String(user.id):'',duration:settings.value.defaultGrant,until:'2026-11-30',reason:''};formError.value='';modal.value='grant';}
function close(){if(!submitting.value){modal.value=null;selected.value=null;formError.value='';}}
async function grant(){const user=users.value.find(u=>u.id===Number(form.value.user));if(!user||!form.value.reason.trim()){formError.value='Selecione um usuário e informe o motivo da concessão.';return;}if(['active','past_due'].includes(user.status)||user.disabled){formError.value='Escolha uma conta habilitada sem cobrança em andamento.';return;}if(form.value.duration==='custom'&&(!form.value.until||form.value.until<='2026-10-30')){formError.value='Escolha uma data posterior a 30/10/2026.';return;}submitting.value=true;await new Promise(r=>setTimeout(r,550));const end=new Date('2026-10-30T12:00:00');end.setDate(end.getDate()+Number(form.value.duration||30));user.status='manual';user.expires=form.value.duration==='forever'?'':form.value.duration==='custom'?form.value.until:end.toISOString().slice(0,10);user.reason=form.value.reason.trim();log('Acesso cortesia concedido',user.name+' · '+(user.expires?'até '+date(user.expires):'sem vencimento')+' · '+user.reason,'grant');submitting.value=false;close();notify('Acesso Pro concedido a '+user.name+'.');}
function openDetails(user){selected.value=user;modal.value='details';}
function revoke(){const user=selected.value;user.status='canceled';user.expires='2026-10-30';log('Cortesia encerrada',user.name+' · acesso retorna ao plano gratuito','grant');close();notify('Cortesia encerrada nesta demonstração.');}
function toggleAccount(){const user=selected.value;user.disabled=!user.disabled;log(user.disabled?'Conta desativada':'Conta reativada',user.name+' · ação manual do administrador');notify(user.disabled?'Conta desativada na demonstração.':'Conta reativada na demonstração.');}
function saveSettings(){settings.value={...draft.value};log('Configurações atualizadas','Preferências gerais e notificações salvas');notify('Configurações salvas no protótipo.');}
function exportCsv(){const data=[['Nome','Email','Status','Origem','Vencimento'],...filtered.value.map(u=>[u.name,u.email,labels[u.status],u.status==='manual'?'Cortesia':u.status==='free'?'Sem assinatura':'Stripe',u.expires])];const content='\ufeff'+data.map(row=>row.map(v=>'"'+String(v||'').replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='fluxo-demonstracao-usuarios.csv';a.click();URL.revokeObjectURL(url);notify('CSV de demonstração exportado.');}
function reset(){localStorage.removeItem(key);users.value=makeUsers();events.value=[...initialEvents];settings.value={...defaults};draft.value={...defaults};close();notify('Dados de demonstração restaurados.');}
function focusSearch(){go('users');nextTick(()=>queryInput.value?.focus());}
function keys(e){if(e.key==='Escape')close();if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();focusSearch();}if(modal.value&&e.key==='Tab'){const items=[...document.querySelectorAll('[role="dialog"] button,[role="dialog"] input,[role="dialog"] select,[role="dialog"] textarea')].filter(el=>!el.disabled&&el.offsetParent!==null&&el.tabIndex>=0);const a=items[0],b=items.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus();}}}
watch(modal,async value=>{document.body.style.overflow=value?'hidden':'';if(value){priorFocus=document.activeElement;await nextTick();document.querySelector('[role="dialog"] button')?.focus();}else priorFocus?.focus();});
watch([search,statusFilter,originFilter],()=>page.value=1);
onMounted(()=>document.addEventListener('keydown',keys));onBeforeUnmount(()=>{document.removeEventListener('keydown',keys);clearTimeout(toastTimer);document.body.style.overflow='';});
</script>


<template>
<div class="admin-shell">
 <div v-if="sidebar" class="mobile-scrim" @click="sidebar=false"></div>
 <aside class="sidebar" :class="{open:sidebar}">
  <a href="#" class="brand" @click.prevent="go('overview')"><span class="brand-symbol"><Layers3 :size="24"/></span>tempozi<span class="brand-dot">.</span></a>
  <a class="admin-exit-link" href="/"><Home :size="17"/> Voltar ao Tempozi</a><div class="workspace-mark"><span class="workspace-icon"><ShieldCheck :size="18"/></span><div><strong>Central de controle</strong><small>Workspace do administrador</small></div><ChevronDown :size="14"/></div>
  <div class="nav-label">PRINCIPAL</div>
  <nav><button v-for="item in nav" :key="item.id" :class="{active:view===item.id}" @click="go(item.id)"><component :is="item.icon" :size="18"/><span>{{item.label}}</span><span v-if="item.id==='subscriptions'" class="nav-badge">{{counts.active}}</span></button></nav>
  <div class="sidebar-note"><div class="note-orbit"><Sparkles :size="20"/></div><strong>Controle com cuidado.</strong><p>Cada acesso é uma pessoa construindo algo com o Tempozi.</p><button @click="modal='help'">Conhecer o painel </button></div>
  <div class="sidebar-bottom"><span class="live-dot"></span> Ambiente de demonstração <button aria-label="Ajuda da administração" @click="modal='help'"><CircleHelp :size="15"/></button></div>
  <button class="admin-account" @click="go('settings')"><span class="avatar owner">NM</span><span><strong>Nicolas Moraes</strong><small>Administrador</small></span><Settings2 :size="16"/></button>
 </aside>
 <div class="main-shell">
  <header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" aria-label="Abrir menu" @click="sidebar=true"><Menu :size="20"/></button><span>Administração</span><strong>{{title}}</strong></div><div class="header-actions"><button class="search-shortcut" @click="focusSearch"><Search :size="16"/><span>Buscar usuário</span><kbd>Ctrl K</kbd></button><button class="icon-button theme-toggle" type="button" role="switch" :aria-checked="theme==='graphite'" :aria-label="theme==='graphite'?'Trocar para tema claro':'Ativar tema escuro Grafite'" :title="theme==='graphite'?'Tema Grafite':'Tema claro'" @click="toggleTheme"><Moon v-if="theme==='graphite'" :size="17"/><Sun v-else :size="17"/></button><button class="icon-button notification-button" aria-label="Ver alertas" @click="modal='notifications'"><Bell :size="18"/><i></i></button><span class="avatar owner small">NM</span></div></header>
  <main>
   <div class="demo-strip"><span><span class="live-dot"></span> PROTÓTIPO INTERATIVO</span><p>Dados de demonstração. As ações ficam apenas neste navegador.</p><button @click="modal='help'">Como explorar </button></div>
   <Transition name="page" mode="out-in"><div :key="view">
    <section class="page-heading"><div><div class="eyebrow">{{view==='overview'?'SEU NEGÓCIO, EM PERSPECTIVA':'CENTRAL DE CONTROLE'}}</div><h1>{{view==='overview'?'Tudo flui por aqui.':title}}<span v-if="view==='overview'" class="title-spark">✳</span></h1><p>{{view==='overview'?'Acompanhe seu crescimento e cuide de quem faz parte do Tempozi.':view==='users'?'Pessoas, acessos e o próximo passo de cada conta.':view==='subscriptions'?'Receita e benefícios, com clareza em cada assinatura.':view==='activity'?'Um registro de cada decisão tomada na administração.':'Deixe o Tempozi do seu jeito, com tudo sob controle.'}}</p></div><div class="heading-actions"><AppSelect v-if="view==='overview'" class="admin-period-select" aria-label="Período do gráfico" v-model="period" :options='[{"label":"Outubro de 2026","value":"month"},{"label":"Últimos 7 dias","value":"week"}]'><template #icon><Clock3 :size="15"/></template></AppSelect><button v-if="view!=='settings'&&view!=='activity'" class="button primary" @click="openGrant()"><Plus :size="16"/> Conceder acesso Pro</button></div></section>
    <template v-if="view==='overview'">
     <section class="welcome-banner"><div class="welcome-copy"><span class="pill pale"><span class="live-dot"></span> UM BOM MOMENTO PARA CRESCER</span><h2>Mais pessoas.<br>Mais ideias em movimento.</h2><p>{{counts.active}} pessoas têm acesso ao Pro. Continue acompanhando o que faz seu produto crescer.</p><button class="text-link" @click="go('users')">Conhecer meus usuários </button></div><div class="hero-art"><img src="/ui/admin-growth.png" alt="Arcos de vidro verde, plantas e degraus de cerâmica, simbolizando crescimento."/></div><span class="art-caption"><Sparkles :size="12"/> Espaço para crescer</span></section>
     <section class="metric-grid">
      <button class="metric-card" @click="go('users')"><div class="metric-top">Total de usuários <span class="metric-icon sage"><Users :size="18"/></span></div><div class="metric-value">{{counts.total}}<span class="trend"> +12</span></div><div class="metric-foot">pessoas no seu workspace </div><svg class="sparkline" viewBox="0 0 120 25"><path d="M0 22L12 19L24 21L36 14L48 16L60 9L72 12L84 6L96 8L108 2L120 0"/></svg></button>
      <button class="metric-card" @click="go('subscriptions','active')"><div class="metric-top">Assinaturas ativas <span class="metric-icon purple"><CreditCard :size="18"/></span></div><div class="metric-value">{{counts.active}}<span class="metric-tag">{{Math.round(counts.active/counts.total*100)}}% da base</span></div><div class="metric-foot">{{counts.paid}} pagas · {{counts.manual}} cortesias </div><div class="mini-progress"><i :style="{width:counts.paid/counts.total*100+'%'}"></i><b :style="{width:counts.manual/counts.total*100+'%'}"></b></div></button>
      <button class="metric-card revenue-card" @click="go('subscriptions');originFilter='paid'"><div class="metric-top">Receita mensal recorrente <span class="metric-icon sage"><BarChart3 :size="18"/></span></div><div class="metric-value currency">{{money(revenue)}}</div><div class="metric-foot"><span><span class="live-dot"></span> Apenas assinaturas pagas</span></div><div class="metric-subtle">Cortesias não entram na receita.</div></button>
      <button class="metric-card" @click="go('subscriptions','canceled')"><div class="metric-top">Assinaturas canceladas <span class="metric-icon peach"><X :size="18"/></span></div><div class="metric-value">{{counts.canceled}}<span class="metric-tag neutral">histórico</span></div><div class="metric-foot">Acompanhar e reconectar </div><div class="metric-subtle">Oportunidades para um novo começo.</div></button>
     </section>
     <div class="analytics-grid">
      <section class="panel growth-panel"><div class="panel-title"><div><h3>O ritmo do seu crescimento</h3><p>Receita recorrente paga · BRL</p></div><span class="pill sage"><span class="live-dot"></span> Demonstrativo</span></div><div class="chart-head"><strong>{{money(revenue)}}</strong><span class="legend"><i></i> Receita recorrente</span></div><div class="line-chart"><div class="y-axis"><span>R$ 1.200</span><span>R$ 900</span><span>R$ 600</span><span>R$ 300</span></div><div class="plot"><div class="chart-grid"></div><svg viewBox="0 0 600 160" preserveAspectRatio="none" role="img" aria-label="Evolução ilustrativa da receita recorrente no período selecionado"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--theme-chart-regular)" stop-opacity=".24"/><stop offset="100%" stop-color="var(--theme-chart-regular)" stop-opacity="0"/></linearGradient></defs><polygon :points="'0,160 '+line+' 600,160'" fill="url(#area)"/><polyline class="chart-line" :points="line" fill="none" stroke="var(--theme-chart-regular)" stroke-width="2.8" vector-effect="non-scaling-stroke"/><circle cx="600" :cy="150-charts.at(-1)*1.4" r="4" fill="var(--theme-chart-regular)" stroke="var(--theme-panel)" stroke-width="2"/></svg><div class="x-axis"><span v-for="label in chartLabels" :key="label">{{label}}</span></div></div></div><div class="chart-footer"><span> Uma visão simples para decisões melhores.</span><button class="text-link" @click="go('subscriptions')">Ver assinaturas </button></div></section>
      <section class="panel distribution-panel"><div class="panel-title"><div><h3>Cada acesso conta</h3><p>Distribuição da sua base</p></div><Users :size="17"/></div><div class="donut-wrap"><div class="donut" :style="{background:'conic-gradient(var(--theme-chart-regular) 0 '+counts.paid/counts.total*100+'%, var(--theme-chart-extra) '+counts.paid/counts.total*100+'% '+counts.active/counts.total*100+'%, var(--theme-line) '+counts.active/counts.total*100+'% 100%)'}"><div><strong>{{counts.total}}</strong><span>usuários</span></div></div><span class="donut-spark">✳</span></div><div class="distribution-row"><span><i style="background:var(--theme-chart-regular)"></i> Pro pago</span><strong>{{counts.paid}}</strong><span>{{Math.round(counts.paid/counts.total*100)}}%</span></div><div class="distribution-row"><span><i style="background:var(--theme-chart-extra)"></i> Pro cortesia</span><strong>{{counts.manual}}</strong><span>{{Math.round(counts.manual/counts.total*100)}}%</span></div><div class="distribution-row"><span><i style="background:var(--theme-line)"></i> Sem Pro ativo</span><strong>{{counts.total-counts.active}}</strong><span>{{Math.round((counts.total-counts.active)/counts.total*100)}}%</span></div></section>
     </div>
     <div class="attention-strip"><span class="attention-icon"><Clock3 :size="18"/></span><div><strong>{{counts.pending}} pagamentos precisam de atenção</strong><p>Uma nova tentativa pode ajudar seus usuários a continuar no Tempozi.</p></div><button class="text-link" @click="go('subscriptions','past_due')">Acompanhar pagamentos </button></div>
     <div class="lower-grid"><section class="panel"><div class="panel-title"><div><h3>Pessoas por trás dos números</h3><p>Uma amostra dos usuários da sua base</p></div><button class="text-link" @click="go('users')">Ver todos </button></div><div class="table-wrap"><table><thead><tr><th>USUÁRIO</th><th>PLANO / SITUAÇÃO</th><th>ACESSO</th></tr></thead><tbody><tr v-for="user in users.slice(0,5)" :key="user.id"><td><button class="user-cell user-link" @click="openDetails(user)"><span class="avatar" :class="'color-'+user.id%4">{{initials(user.name)}}</span><span><strong>{{user.name}}</strong><small>{{user.email}}</small></span></button></td><td><span class="status-badge" :class="user.status"><i></i>{{labels[user.status]}}</span></td><td><button class="icon-button" :aria-label="'Ver '+user.name" @click="openDetails(user)"><Eye :size="16"/></button></td></tr></tbody></table></div></section>
     <section class="panel timeline-panel"><div class="panel-title"><div><h3>Acontecendo no Tempozi</h3><p>Os últimos movimentos da sua base</p></div><span class="tiny-dot"></span></div><div class="timeline"><div v-for="event in events.slice(0,3)" :key="event.id" class="timeline-item"><span class="timeline-icon" :class="event.type"><Gift v-if="event.type==='grant'" :size="15"/><CreditCard v-else-if="event.type==='subscription'" :size="15"/><Clock3 v-else :size="15"/></span><div><strong>{{event.title}}</strong><p>{{event.detail}}</p><small>{{event.time}}</small></div></div></div><button class="timeline-more" @click="go('activity')">Abrir histórico completo </button></section></div>
    </template>


    <template v-else-if="view==='users'||view==='subscriptions'">
     <div class="summary-pills"><button :class="{selected:statusFilter==='all'}" @click="statusFilter='all'">Todos <b>{{view==='users'?counts.total:counts.total-counts.free}}</b></button><button :class="{selected:statusFilter==='active'}" @click="statusFilter='active'"><i class="dot-green"></i> Ativas <b>{{counts.active}}</b></button><button :class="{selected:statusFilter==='manual'}" @click="statusFilter='manual'">Cortesias <b>{{counts.manual}}</b></button><button :class="{selected:statusFilter==='past_due'}" @click="statusFilter='past_due'">Pendentes <b>{{counts.pending}}</b></button><button :class="{selected:statusFilter==='canceled'}" @click="statusFilter='canceled'">Canceladas <b>{{counts.canceled}}</b></button></div>
     <section class="panel directory"><div class="directory-tools"><label class="search-field"><Search :size="17"/><input ref="queryInput" v-model="search" placeholder="Buscar por nome ou e-mail" aria-label="Buscar por nome ou e-mail"/><button v-if="search" aria-label="Limpar busca" @click="search=''"><X :size="14"/></button></label><div class="table-actions"><AppSelect class="admin-origin-select" aria-label="Filtrar origem" v-model="originFilter" :options='[{"label":"Todas as origens","value":"all"},{"label":"Pagamento Stripe","value":"paid"},{"label":"Concessão manual","value":"manual"}]'><template #icon><SlidersHorizontal :size="15"/></template></AppSelect><button class="button" @click="exportCsv"><Download :size="15"/> Exportar CSV</button></div></div>
      <div class="table-wrap"><table><thead><tr><th>USUÁRIO</th><th>PLANO / SITUAÇÃO</th><th>ORIGEM</th><th>{{view==='subscriptions'?'RENOVAÇÃO / FIM':'CADASTRO'}}</th><th>VALOR MENSAL</th><th></th></tr></thead><tbody><tr v-for="user in rows" :key="user.id"><td><button class="user-cell user-link" @click="openDetails(user)"><span class="avatar" :class="'color-'+user.id%4">{{initials(user.name)}}</span><span><strong>{{user.name}}<span v-if="user.disabled" class="disabled-tag">desativada</span></strong><small>{{user.email}}</small></span></button></td><td><span class="status-badge" :class="user.status"><i></i>{{labels[user.status]}}</span></td><td><span class="origin" :class="{gift:user.status==='manual'}"><Gift v-if="user.status==='manual'" :size="13"/>{{user.status==='manual'?'Manual':user.status==='free'?'—':'Stripe'}}</span></td><td>{{view==='subscriptions'?(user.expires?date(user.expires):'Sem vencimento'):date(user.joined)}}</td><td class="amount">{{user.status==='active'?money(19.9):money(0)}}<small v-if="user.status==='manual'">cortesia</small></td><td><button class="icon-button" :aria-label="'Ver detalhes de '+user.name" @click="openDetails(user)"><MoreHorizontal :size="19"/></button></td></tr></tbody></table><div v-if="!rows.length" class="empty-state"><Search :size="30"/><h3>Nenhum usuário por aqui.</h3><p>Tente outro nome, e-mail ou combinação de filtros.</p><button class="button" @click="search='';statusFilter='all';originFilter='all'">Limpar filtros</button></div></div>
      <footer class="pagination"><span>{{filtered.length}} resultados · dados de demonstração</span><div><button class="button" :disabled="page<=1" @click="page--">Anterior</button><span>{{Math.min(page,totalPages)}} de {{totalPages}}</span><button class="button" :disabled="page>=totalPages" @click="page++">Próxima </button></div></footer>
     </section>
     <div class="courtesy-explainer"><Gift :size="20"/><div><strong>Um gesto de incentivo também é Pro.</strong><p>Conceda benefícios sem cobrança para parceiros, equipe ou usuários que merecem um cuidado extra. Toda concessão tem motivo e histórico.</p></div><button class="text-link" @click="openGrant()">Conceder cortesia </button></div>
    </template>
    <template v-else-if="view==='activity'"><section class="panel activity-list"><div class="panel-title"><div><h3>Histórico administrativo</h3><p>Concessões, configurações e alterações de acesso.</p></div><span class="pill sage">{{events.length}} eventos</span></div><div class="timeline"><div v-for="event in events" :key="event.id" class="timeline-item"><span class="timeline-icon" :class="event.type"><Gift v-if="event.type==='grant'" :size="17"/><ShieldCheck v-else :size="17"/></span><div><strong>{{event.title}}</strong><p>{{event.detail}}</p><small>{{event.time}}</small></div><span class="event-label">Demonstração</span></div></div></section></template>
    <template v-else-if="view==='settings'"><div class="settings-layout"><div class="settings-index"><span class="settings-selected"><Settings2 :size="16"/> Preferências gerais</span><p>Estas configurações são simuladas. Salvar registra a alteração neste navegador.</p><div class="settings-art"><img src="/ui/admin-growth.png" alt="Arcos verdes de vidro com plantas"/><strong>Uma boa base<br>para continuar crescendo.</strong></div></div>
     <form class="settings-form" @submit.prevent="saveSettings"><section class="panel setting-section"><div class="panel-title"><div><h3>A identidade do seu espaço</h3><p>Informações de contato da administração.</p></div></div><div class="field-grid"><label>Nome do produto<input v-model="draft.name" required maxlength="50"/></label><label>E-mail de suporte<input v-model="draft.email" type="email" required/></label></div></section>
     <section class="panel setting-section"><div class="panel-title"><div><h3>Assinaturas e benefícios</h3><p>Preferências para novos acessos e concessões.</p></div><CreditCard :size="19"/></div><div class="field-grid"><label>Período padrão de cortesia<AppSelect v-model="draft.defaultGrant" block :options='[{"label":"7 dias","value":"7"},{"label":"30 dias","value":"30"},{"label":"90 dias","value":"90"}]'/></label><label>Tolerância para pagamentos<AppSelect v-model="draft.grace" block :options='[{"label":"Sem tolerância","value":"0"},{"label":"3 dias","value":"3"},{"label":"7 dias","value":"7"}]'/></label></div><div class="inline-note"><ShieldCheck :size="17"/><p>Credenciais de cobrança e permissões de administrador serão gerenciadas pelo servidor na implementação definitiva.</p></div></section>
     <section class="panel setting-section"><div class="panel-title"><div><h3>Comunicação e disponibilidade</h3><p>Como o Tempozi conversa com a sua base.</p></div></div><label class="toggle-row"><span><strong>Novos cadastros</strong><small>Permitir a criação de novas contas.</small></span><input v-model="draft.newAccounts" type="checkbox" role="switch"/><span class="toggle"></span></label><label class="toggle-row"><span><strong>Notificações de cobrança</strong><small>Avisos de renovação e pagamento pendente.</small></span><input v-model="draft.billingEmails" type="checkbox" role="switch"/><span class="toggle"></span></label><label class="toggle-row"><span><strong>Alertas administrativos</strong><small>Receber atualizações sobre ações importantes.</small></span><input v-model="draft.securityEmails" type="checkbox" role="switch"/><span class="toggle"></span></label><label class="toggle-row"><span><strong>Modo de manutenção</strong><small>Exibir um aviso temporário de indisponibilidade.</small></span><input v-model="draft.maintenance" type="checkbox" role="switch"/><span class="toggle"></span></label></section><div class="settings-actions"><button type="button" class="button" @click="draft={...settings};notify('Alterações não salvas descartadas.')">Descartar alterações</button><button class="button primary"><Check :size="16"/> Salvar configurações</button></div><button type="button" class="reset-link" @click="modal='reset'"><RefreshCw :size="13"/> Restaurar dados de demonstração</button></form>
    </div></template>
    <footer class="page-footer"><span class="footer-brand"><Layers3 :size="15"/> tempozi.</span><span>Feito para manter as coisas em movimento.</span><span>Protótipo · Outubro de 2026</span></footer>
   </div></Transition>
  </main>
 </div>
 <Transition name="toast"><div v-if="toast" class="toast" role="status"><CheckCircle2 :size="20"/>{{toast}}<button aria-label="Fechar aviso" @click="toast=''"><X :size="15"/></button></div></Transition>
 <Transition name="modal"><div v-if="modal" class="modal-backdrop" @click.self="close()"><section class="modal-card" :class="{wide:modal==='grant'}" role="dialog" aria-modal="true" aria-labelledby="dialog-title">
  <button class="modal-close icon-button" aria-label="Fechar janela" :disabled="submitting" @click="close()"><X :size="20"/></button>
  <template v-if="modal==='grant'"><div class="modal-icon"><Gift :size="25"/></div><span class="eyebrow">UM INCENTIVO PARA IR ALÉM</span><h2 id="dialog-title">O próximo passo é por sua conta.</h2><p class="modal-description">Conceda acesso ao Tempozi Pro sem gerar cobrança. Uma cortesia com propósito, prazo e transparência.</p><form @submit.prevent="grant"><div class="recipient-field"><label for="grant-recipient">Quem vai receber?</label><UserSearchSelect v-model="form.user" :users="grantTargets"/><small>Contas desativadas e cobranças Stripe em andamento não são elegíveis.</small></div><label>Por quanto tempo?<AppSelect v-model="form.duration" block :options='[{"label":"7 dias","value":"7"},{"label":"30 dias","value":"30"},{"label":"90 dias","value":"90"},{"label":"Escolher uma data","value":"custom"},{"label":"Sem vencimento","value":"forever"}]'/></label><label v-if="form.duration==='custom'">Último dia do acesso<input type="date" v-model="form.until" min="2026-10-31" required/></label><label>Motivo da concessão<textarea v-model="form.reason" placeholder="Ex.: parceria, teste acompanhado ou benefício para a equipe." required maxlength="300" rows="3"></textarea><small>Esse motivo será registrado no histórico administrativo.</small></label><div class="grant-summary"><span class="plan-mark"><Sparkles :size="20"/></span><div><strong>Tempozi Pro · cortesia</strong><small>Todos os benefícios, sem cobrança automática.</small></div><strong>R$ 0,00</strong></div><p v-if="formError" class="error-message" role="alert">{{formError}}</p><div class="modal-actions"><button type="button" class="button" :disabled="submitting" @click="close()">Cancelar</button><button class="button primary" :disabled="submitting"><RefreshCw v-if="submitting" :size="16" class="spin"/><Gift v-else :size="16"/>{{submitting?'Concedendo…':'Confirmar cortesia'}}</button></div></form><p class="modal-footnote">Simulação: nenhuma assinatura ou cobrança real será alterada.</p></template>
  <template v-else-if="modal==='details'&&selected"><div class="detail-head"><span class="avatar large" :class="'color-'+selected.id%4">{{initials(selected.name)}}</span><span class="pill sage">USUÁRIO #{{String(selected.id).padStart(4,'0')}}</span></div><h2 id="dialog-title">{{selected.name}}</h2><p class="modal-description">{{selected.email}}</p><span class="status-badge" :class="selected.status"><i></i>{{labels[selected.status]}}</span><div class="detail-grid"><div><small>CADASTRO</small><strong>{{dateFull(selected.joined)}}</strong></div><div><small>CONTA</small><strong>{{selected.disabled?'Desativada':'Habilitada'}}</strong></div><div><small>ORIGEM DO ACESSO</small><strong>{{selected.status==='manual'?'Concessão manual':selected.status==='free'?'Plano gratuito':'Stripe'}}</strong></div><div><small>{{selected.status==='manual'?'FIM DA CORTESIA':'PRÓXIMA RENOVAÇÃO'}}</small><strong>{{selected.expires?dateFull(selected.expires):'Sem vencimento'}}</strong></div></div><div v-if="selected.reason" class="inline-note"><Gift :size="17"/><p>{{selected.reason}}</p></div><div class="detail-actions"><button v-if="!['active','past_due'].includes(selected.status)&&!selected.disabled" class="button primary" @click="openGrant(selected)"><Gift :size="15"/>{{selected.status==='manual'?'Renovar cortesia':'Conceder Pro'}}</button><button v-if="selected.status==='manual'" class="button danger" @click="modal='revoke'">Encerrar cortesia</button><div v-if="['active','past_due'].includes(selected.status)" class="inline-note">Assinatura paga: cancelamento e reembolso serão gerenciados pela integração de cobrança.</div><button class="text-link muted" @click="toggleAccount">{{selected.disabled?'Reativar conta':'Desativar conta'}} </button></div></template>
  <template v-else-if="modal==='revoke'"><div class="modal-icon warning"><Gift :size="25"/></div><h2 id="dialog-title">Encerrar esta cortesia?</h2><p class="modal-description">{{selected?.name}} voltará ao plano gratuito. Os dados da conta serão preservados e a ação aparecerá no histórico.</p><div class="modal-actions"><button class="button" @click="modal='details'">Voltar</button><button class="button danger" @click="revoke">Encerrar cortesia</button></div></template>
  <template v-else-if="modal==='notifications'"><div class="modal-icon"><Bell :size="24"/></div><h2 id="dialog-title">Um pouco de atenção por aqui.</h2><p class="modal-description">Alertas de demonstração da sua operação.</p><button class="notification-card" @click="close();go('subscriptions','past_due')"><Clock3 :size="20"/><span><strong>{{counts.pending}} pagamentos pendentes</strong><small>Veja as assinaturas que precisam de acompanhamento.</small></span></button><button class="notification-card" @click="close();go('subscriptions','manual')"><Gift :size="20"/><span><strong>{{counts.manual}} acessos cortesia</strong><small>Acompanhe os benefícios concedidos manualmente.</small></span></button></template>
  <template v-else-if="modal==='reset'"><div class="modal-icon warning"><RefreshCw :size="24"/></div><h2 id="dialog-title">Começar a demonstração de novo?</h2><p class="modal-description">As concessões, configurações e ações feitas neste protótipo serão apagadas apenas deste navegador.</p><div class="modal-actions"><button class="button" @click="close()">Cancelar</button><button class="button danger" @click="reset">Restaurar demonstração</button></div></template>
  <template v-else><div class="modal-icon"><Sparkles :size="25"/></div><h2 id="dialog-title">Um painel para cuidar do Tempozi.</h2><p class="modal-description">Explore as telas, pesquise usuários e conceda acesso Pro de cortesia. Os dados são fictícios e as alterações ficam neste navegador.</p><div class="help-steps"><div><span>01</span><p><strong>Acompanhe</strong>Usuários, receita paga e cortesias em um só lugar.</p></div><div><span>02</span><p><strong>Experimente</strong>Filtre a base, abra os detalhes e conceda uma cortesia.</p></div><div><span>03</span><p><strong>Tenha contexto</strong>Veja cada ação no histórico e personalize as preferências.</p></div></div><button class="button primary full" @click="close()">Explorar painel </button></template>
 </section></div></Transition>
</div>
</template>
